<article class="card shadow-sm printable"><div class="card-body p-4"><div class="d-flex justify-content-between"><div><h1 class="h3">ISHEP Invoice</h1><p><?=e($invoice['invoice_number'])?></p></div><button class="btn btn-outline-secondary no-print" onclick="window.print()">Print</button></div><hr><dl class="row"><dt class="col-4">Member</dt><dd class="col-8"><?=e($invoice['member_name'])?></dd><dt class="col-4">Membership</dt><dd class="col-8"><?=e($invoice['membership_number'])?></dd><dt class="col-4">Issued</dt><dd class="col-8"><?=e($invoice['issued_at'])?></dd><dt class="col-4">Status</dt><dd class="col-8"><?=e(str_replace('_',' ',$invoice['status']))?></dd></dl><table class="table"><thead><tr><th>Description</th><th>Quantity</th><th>Unit amount</th><th>Total</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?=e($item['description'])?></td><td><?=e($item['quantity'])?></td><td><?=e($invoice['currency'].' '.$item['unit_amount'])?></td><td><?=e($invoice['currency'].' '.$item['line_total'])?></td></tr><?php endforeach;?></tbody><tfoot><tr><th colspan="3">Paid</th><td><?=e($invoice['currency'].' '.$invoice['amount_paid'])?></td></tr><tr><th colspan="3">Balance due</th><td><strong><?=e($invoice['currency'].' '.$invoice['balance_due'])?></strong></td></tr></tfoot></table><p class="small text-muted">This invoice records ISHEP's internal account position. Manually recorded payments are not external bank confirmations.</p></div></article>
